script:
frappe.ui.form.on("Library Member",{
    refresh(frm){
        frm.add_custom_button("Create Contact",() =>{
            let dialog=new frappe.ui.Dialog({
                title:"Create Contact",
                fields:[
                    {
                        label:"First Name",
                        fieldname:"first_name",
                        fieldtype:"Data",
                        reqd:1
                    }
                ],
                primary_action_label:"Create Contact",
                primary_action(values){
                    let first_name=values.first_name;
                    dialog.hide();
                    frappe.route_options={
                        first_name:first_name
                    };
                    frappe.new_doc("Contact");
                }
            });
            dialog.show();
        });
    }
});

frappe.ui.form.on("Library Member", {

    refresh(frm) {
        frappe.msgprint("Welcome to Library Member Form!");
        if (frm.is_new()) {
            frappe.msgprint("Create a New Member");
        }
    },

    full_name(frm) {
        frm.set_value("full_name", frm.doc.full_name.toUpperCase());
    }
});

frappe.listview_settings["Library Member"] = {
    onload(listview) {
        frappe.show_alert({
            message: "Library Member List Loaded",
            indicator: "green"
        });
    },
    onload(listview) {
        listview.page.add_inner_button("Say Hello", function () {
            frappe.msgprint("Hello from List View!");
        });
    },
    onload(listview) {
        listview.page.add_inner_button("Selected Count", function () {
            let selected = listview.get_checked_items();
            frappe.msgprint(
                "Selected Members: " + selected.length
            );
        });
    },
    refresh(listview) {
        console.log("List Refreshed");
    }
};

frappe.ui.form.on("User", {
    refresh(frm) {
        frm.add_custom_button("Send Welcome Email", function() {
            frappe.msgprint("Email Sent!");
        }, "Actions");
    }
});
